#include "deterministic-shard-top-letter.h"

std::optional<std::optional<std::pair<char,std::size_t>>> charm::v1n7::parallel_letter_frequency::parallel_top_lowercase(const std::vector<std::string>& shards,std::size_t worker_count){if(worker_count==0)return std::nullopt;if(shards.empty())return std::optional<std::pair<char,std::size_t>>{};std::size_t workers=std::min(worker_count,shards.size());std::vector<std::future<std::array<std::size_t,26>>> jobs;for(std::size_t w=0;w<workers;++w)jobs.push_back(std::async(std::launch::async,[&,w]{std::array<std::size_t,26> counts{};for(std::size_t i=w;i<shards.size();i+=workers)for(unsigned char c:shards[i])if(c>='a'&&c<='z')++counts[c-'a'];return counts;}));std::array<std::size_t,26> total{};for(auto& job:jobs){auto part=job.get();for(std::size_t i=0;i<26;++i)total[i]+=part[i];}auto it=std::max_element(total.begin(),total.end());if(*it==0)return std::optional<std::pair<char,std::size_t>>{};return std::optional<std::pair<char,std::size_t>>{{static_cast<char>('a'+std::distance(total.begin(),it)),*it}};}
